1	package security
2	
3	import (
4		"fmt"
5		"log"
6		"strings"
7	
8		tea "charm.land/bubbletea/v2"
9		"charm.land/lipgloss/v2"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/browser"
13		"github.com/anthnel/devdesk/internal/scan"
14		"github.com/anthnel/devdesk/internal/ui/keymap"
15		"github.com/anthnel/devdesk/internal/ui/theme"
16	)
17	
18	// handleDetailsState processes input in details state
19	func (m Model) handleDetailsState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
20		switch msg.String() {
21		// backspace was an alias of esc, and the only one in the application.
22		case "esc":
23			m.state = StateResults
24			return m, nil
25		case keymap.Web:
26			return m.handleDetailsOpenReference()
27		case "up":
28			m.detailsViewport.ScrollUp(1)
29		case "down":
30			m.detailsViewport.ScrollDown(1)
31		case "pgup":
32			m.detailsViewport.HalfPageUp()
33		case "pgdown":
34			m.detailsViewport.HalfPageDown()
35		case "home":
36			m.detailsViewport.GotoTop()
37		case "end":
38			m.detailsViewport.GotoBottom()
39		}
40		return m, nil
41	}
42	
43	// handleDetailsOpenReference opens the first reference URL in the default browser.
44	func (m Model) handleDetailsOpenReference() (tea.Model, tea.Cmd) {
45		if m.selectedFinding == nil {
46			return m, nil
47		}
48		f := *m.selectedFinding
49		if len(f.References) == 0 {
50			return m, m.footer.Warn("No references available")
51		}
52		url := f.References[0]
53		return m, func() tea.Msg {
54			if err := browser.Open(url); err != nil {
55				log.Printf("ERROR [security] open URL %s: %v", url, err)
56			}
57			return nil
58		}
59	}
60	
61	// sizeDetails gives the details viewport the room the router leaves it: the
62	// view's width less the two border cells the viewport frame takes, so a line
63	// never reaches under the right border. The padding takes one more cell on each
64	// side, which is the text width (detailsTextWidth).
65	func (m *Model) sizeDetails() {
66		m.detailsViewport.SetWidth(max(m.width-2, 1))
67		m.detailsViewport.SetHeight(m.height)
68	}
69	
70	// detailsTextWidth is how many cells a line of the detail text may span.
71	func (m Model) detailsTextWidth() int { return max(m.width-4, 1) }
72	
73	// scanTarget is the scanned path, for display only: it is what shortPaths cuts
74	// off a path, and an image reference there is ignored.
75	func (m Model) scanTarget() string {
76		if m.result == nil {
77			return ""
78		}
79		return m.result.Target
80	}
81	
82	// targetOnDisk says whether the scanned target is a directory, whose files a
83	// built-in fix can write.
84	func (m Model) targetOnDisk() bool {
85		return m.result != nil && m.result.TargetType == scan.TargetDirectory
86	}
87	
88	// buildDetailsContent builds the full scrollable content for the details view.
89	//
90	// What to do comes before what it is: the fix status and the remediation, then
91	// the scanner's message, then the facts. Each section is emitted only when it has
92	// something to say, and sections are joined by exactly one blank line.
93	func (m Model) buildDetailsContent() string {
94		if m.selectedFinding == nil {
95			return theme.Bg("No finding selected")
96		}
97	
98		f := *m.selectedFinding
99		t := newDetailsText(m.detailsTextWidth())
100	
101		var sections []string
102		for _, section := range [][]string{
103			m.detailsHeader(f, t),
104			m.detailsFix(f, t),
105			m.detailsMessage(f, t),
106			m.detailsDescription(f, t),
107			m.detailsFacts(f, t),
108			m.detailsScript(f, t),
109			m.detailsReferences(f, t),
110		} {
111			if len(section) > 0 {
112				sections = append(sections, strings.Join(section, "\n"))
113			}
114		}
115	
116		return lipgloss.NewStyle().
117			Padding(1).
118			Background(theme.ColorBackground).
119			Render(strings.Join(sections, "\n\n"))
120	}
121	
122	// detailsHeader is the severity and ID, then the title on one line: a title can
123	// carry a whole stderr line, and the Message below has the rest.
124	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
125		sev := string(f.Severity)
126		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
127			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
128		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
129		return []string{header, t.text.Render(title)}
130	}
131	
132	// detailsFix is the fix status in words, then the remediation: the Resolution
133	// and either the command to run or, for a sentence such as "Update pkg to 1.2",
134	// the instruction as text.
135	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
136		var lines []string
137		status := fixStatusOf(f, m.targetOnDisk())
138		if label := status.Label(); label != "" {
139			lines = append(lines, t.field("Fix status: ", label, t.text)...)
140			lines = append(lines, t.block(status.Effect, t.dim)...)
141			if status.Warning != "" {
142				lines = append(lines, t.field("Warning: ", status.Warning, theme.StatusWarningStyle)...)
143			}
144		}
145		label, action := fixAction(f)
146		if f.Resolution == "" && action == "" {
147			return lines
148		}
149		lines = append(lines, theme.SubTitleStyle.Render("Remediation:"))
150		lines = append(lines, t.block(f.Resolution, t.text)...)
151		if label != "" {
152			return append(lines, t.field(label+": ", action, t.text)...)
153		}
154		return append(lines, t.block(action, t.text)...)
155	}
156	
157	// detailsMessage is what the scanner said about this instance, capped: the start
158	// of it is what tells two findings of one rule apart, and the rest is in the log.
159	// A message that only repeats the title or the description adds nothing.
160	func (m Model) detailsMessage(f scan.Finding, t detailsText) []string {
161		msg := strings.TrimSpace(f.Message)
162		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
163			return nil
164		}
165		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
166		if len(lines) == 0 {
167			return nil
168		}
169		out := []string{theme.SubTitleStyle.Render("Message:")}
170		for _, line := range lines {
171			out = append(out, t.text.Render(line))
172		}
173		if more := moreLines(hidden); more != "" {
174			out = append(out, theme.DimStyle.Render(more))
175		}
176		return out
177	}
178	
179	func (m Model) detailsDescription(f scan.Finding, t detailsText) []string {
180		if strings.TrimSpace(f.Description) == "" {
181			return nil
182		}
183		return append([]string{theme.SubTitleStyle.Render("Description:")}, t.block(f.Description, t.text)...)
184	}
185	
186	// detailsFacts are the labelled values, each wrapped under its label.
187	func (m Model) detailsFacts(f scan.Finding, t detailsText) []string {
188		var lines []string
189		add := func(label, value string, style lipgloss.Style) {
190			if value != "" {
191				lines = append(lines, t.field(label+": ", value, style)...)
192			}
193		}
194		add("Source", f.Source, t.text)
195		add("Type", f.IaCType, t.text)
196		add("Pod Security", pssLabel(f), t.text)
197		add("File", shortPaths(f.File, m.scanTarget()), t.text)
198		if f.Line > 0 {
199			add("Line", fmt.Sprintf("%d", f.Line), t.text)
200		}
201		if f.PkgName != "" {
202			add("Package", f.PkgName, t.text)
203			add("Kind", packageKind(f.Class), t.text)
204			add("Version", f.Version, t.text)
205			add("Fixed In", f.FixedIn, theme.StatusOKStyle)
206		}
207		add("Match", f.Match, t.text)
208		return lines
209	}
210	
211	// detailsScript is the offending line of a CI finding, wrapped: it is a shell
212	// command and can be long. It is the only thing plumber says about *where inside
213	// a job* a control fired — the File names the `include:` entry that brought the
214	// job in, which is the include responsible rather than the fault.
215	func (m Model) detailsScript(f scan.Finding, t detailsText) []string {
216		if strings.TrimSpace(f.ScriptLine) == "" {
217			return nil
218		}
219		return append([]string{theme.SubTitleStyle.Render("Script:")}, t.block(f.ScriptLine, t.text)...)
220	}
221	
222	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
223		if len(f.References) == 0 {
224			return nil
225		}
226		lines := []string{theme.SubTitleStyle.Render("References:")}
227		for _, ref := range f.References {
228			lines = append(lines, t.indented("  ", ref, t.text)...)
229		}
230		return lines
231	}
232	
233	// renderDetailsView renders the scrollable details viewport.
234	func (m Model) renderDetailsView() string {
235		return m.detailsViewport.View()
236	}
237	
238	// getSeverityStyle returns style for severity level (Rule 102: the palette
239	// lives in the theme, not here).
240	func (m Model) getSeverityStyle(sev scan.SeverityLevel) lipgloss.Style {
241		return theme.SeverityTextStyle(string(sev))
242	}
243	
244	// HeaderView interface implementation
245	
246	// packageKind says what has to move to clear a vulnerability, from the class
247	// Trivy reported. Empty for a result cached before the class was recorded: it
248	// is unknown, and is not shown rather than guessed.
249	func packageKind(class string) string {
250		switch class {
251		case scan.ClassOSPackages:
252			return "Base image package"
253		case scan.ClassLangPackages:
254			return "Application dependency"
255		}
256		return ""
257	}
