1	package security
2	
3	import (
4		"strings"
5		"testing"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/remediation"
10		"github.com/anthnel/devdesk/internal/scan"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12	)
13	
14	// DEVDESK-751 (steps 1 and 2): the closed vocabulary of the Fix line of the
15	// finding detail, and the one computation it shares with the shortcut column
16	// (Rule 130). It replaces the DEVDESK-750 labels ("Fix available", "No fix
17	// available", "No built-in fix here", ...).
18	
19	func misconfigOf(id string) scan.Finding {
20		return scan.Finding{ID: id, Title: "A misconfiguration", Severity: scan.SeverityHigh,
21			Source: scan.SourceTrivyMisconfig, File: "Dockerfile", Line: 1, EndLine: 3}
22	}
23	
24	func unconfinedSeccomp() scan.Finding {
25		f := misconfigOf("KSV-0104")
26		f.File, f.SeccompOrigin = "pod.yaml", "unconfined"
27		return f
28	}
29	
30	// withResolution is f with a Resolution sentence, the guidance a scanner gives.
31	func withResolution(f scan.Finding) scan.Finding {
32		f.Resolution = "Rotate the credential and remove it from the history."
33		return f
34	}
35	
36	func TestFixStatusOf(t *testing.T) {
37		builtIn, ok := remediation.FixFor(misconfigOf("DS002"))
38		if !ok {
39			t.Fatal("DS002 is no longer in the catalog: pick another built-in rule")
40		}
41		hostNS, ok := remediation.FixFor(misconfigOf("KSV-0009"))
42		if !ok || hostNS.Warning == "" {
43			t.Fatal("KSV-0009 must be a catalog rule with a Warning")
44		}
45		declines := unconfinedSeccomp()
46		declineReason := ""
47		if rule, ok := remediation.FixFor(declines); ok && rule.Declines != nil {
48			declineReason = rule.Declines(declines)
49		}
50		if declineReason == "" {
51			t.Fatal("KSV-0104 unconfined must decline from the finding alone")
52		}
53		if _, ok := remediation.MissingFor(misconfigOf("KSV-0012")); !ok {
54			t.Fatal("KSV-0012 must have a MissingFor text")
55		}
56		if _, ok := remediation.MissingFor(misconfigOf("KSV-0003")); ok {
57			t.Fatal("KSV-0003 must have no MissingFor text: it is the no-guidance rule of these tests")
58		}
59		cve := scan.Finding{ID: "CVE-1", Source: scan.SourceTrivy, FixedIn: "1.2.3"}
60	
61		tests := []struct {
62			name      string
63			f         scan.Finding
64			onDisk    bool
65			want      fixStatus
66			wantLabel string
67			// loose compares State and Reason only: the plan does not say what
68			// Effect and Warning hold for this row.
69			loose bool
70		}{
71			{"built-in fix on disk", misconfigOf("DS002"), true,
72				fixStatus{State: fixBuiltIn, Effect: builtIn.Title, Warning: builtIn.Warning}, labelBuiltInAvailable, false},
73			{"built-in fix with a warning", misconfigOf("KSV-0009"), true,
