341					status := fixStatusOf(f, kind == scan.TargetDirectory)
342					switch _, inCatalog := remediation.FixFor(f); {
343					case kind == scan.TargetImage:
344						if status.State != fixCannotFixHere || status.Reason != reasonFileNotOnDisk {
345							t.Errorf("on an image the status is %+v, want Cannot fix here with %q", status, reasonFileNotOnDisk)
