154	func TestFindingFilePath(t *testing.T) {
155		const target = "/repo"
156		under := func(parts ...string) string { return filepath.Join(append([]string{target}, parts...)...) }
157		tests := []struct {
158			name       string
159			file       string
160			target     string
161			onDisk     bool
162			want       string
163			wantReason string
164		}{
165			{"a relative path is joined to the target", "k/x.yaml", target, true, under("k", "x.yaml"), ""},
166			{"a path under the container mount is moved to the target", "/scan/k/x.yaml", target, true, under("k", "x.yaml"), ""},
167			{"an absolute path under the target is kept", "/repo/k/x.yaml", target, true, under("k", "x.yaml"), ""},
168			{"a target with a trailing slash", "k/x.yaml", target + "/", true, under("k", "x.yaml"), ""},
169			{"a dot segment inside the target is cleaned", "k/./y/../x.yaml", target, true, under("k", "x.yaml"), ""},
170			{"a parent segment out of the target", "../etc/passwd", target, true, "", reasonFileOutsideTarget},
171			{"a parent segment hidden in a path", "k/../../etc/passwd", target, true, "", reasonFileOutsideTarget},
172			{"an absolute path outside the target", "/etc/passwd", target, true, "", reasonFileOutsideTarget},
173			{"a sibling that shares the target as a prefix", "/repo-evil/x", target, true, "", reasonFileOutsideTarget},
174			{"an absolute path that climbs out of the target", "/repo/../etc/passwd", target, true, "", reasonFileOutsideTarget},
175			{"the container mount that climbs out", "/scan/../etc/passwd", target, true, "", reasonFileOutsideTarget},
176			{"no file", "", target, true, "", reasonNoFile},
177			{"an image target has no file on disk", "k/x.yaml", "app:1.0", false, "", reasonFileNotOnDisk},
178			{"an image target, whatever the file", "/etc/passwd", "app:1.0", false, "", reasonFileNotOnDisk},
179		}
180		for _, tc := range tests {
181			t.Run(tc.name, func(t *testing.T) {
182				got, a := findingFilePath(scan.Finding{File: tc.file}, tc.target, tc.onDisk)
183				if a.Reason != tc.wantReason {
184					t.Errorf("reason = %q, want %q", a.Reason, tc.wantReason)
185				}
186				if a.Enabled() != (tc.wantReason == "") {
187					t.Errorf("Enabled() = %v for reason %q", a.Enabled(), a.Reason)
188				}
189				if got != tc.want {
190					t.Errorf("path = %q, want %q", got, tc.want)
191				}
192			})
