200	func TestFindingFilePathDoesNotTouchTheDisk(t *testing.T) {
201		_, a := findingFilePath(scan.Finding{File: "no/such/file.yaml"}, "/definitely/not/a/directory", true)
202		if !a.Enabled() {
203			t.Errorf("a file that may not exist is refused (%q): the viewer says so, not the header", a.Reason)
204		}
