206		entries, err := os.ReadDir(".")
207		if err != nil {
208			t.Fatal(err)
209		}
210		fset := token.NewFileSet()
211		found := false
212		for _, entry := range entries {
213			name := entry.Name()
214			if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
215				continue
216			}
217			file, err := parser.ParseFile(fset, name, nil, 0)
218			if err != nil {
219				t.Fatal(err)
220			}
221			for _, decl := range file.Decls {
222				fn, ok := decl.(*ast.FuncDecl)
223				if !ok || fn.Name.Name != "findingFilePath" || fn.Body == nil {
224					continue
