231					}
232					if id, ok := sel.X.(*ast.Ident); ok && (id.Name == "os" || id.Name == "ioutil" || id.Name == "fs") {
233						t.Errorf("findingFilePath calls %s.%s: it must do no I/O", id.Name, sel.Sel.Name)
234					}
