251		tests := []struct {
252			name string
253			a, b scan.Finding
254			want bool
255		}{
256			{"the same finding", base, base, true},
257			{"the same finding on another line, as the fix moves it", base, with(base, func(f *scan.Finding) { f.Line += 1 }), true},
258			{"a new description is the same finding", base, with(base, func(f *scan.Finding) { f.Description = "Reworded" }), true},
259			{"another message", base, with(base, func(f *scan.Finding) { f.Message = "Container 'sidecar' of Deployment 'app'" }), false},
260			{"another title", base, with(base, func(f *scan.Finding) { f.Title = "Another title" }), false},
261			{"another file", base, with(base, func(f *scan.Finding) { f.File = "other.yaml" }), false},
