264			{"a rule written with its AVD id is the same rule", with(base, func(f *scan.Finding) { f.ID = "DS002" }),
265				with(base, func(f *scan.Finding) { f.ID = "AVD-DS-0002" }), true},
266			{"the same CVE", cve, cve, true},
267			{"another version of the package", cve, with(cve, func(f *scan.Finding) { f.Version = "0.2.0" }), false},
268			{"another package", cve, with(cve, func(f *scan.Finding) { f.PkgName = "golang.org/x/text" }), false},
269			{"another CVE", cve, with(cve, func(f *scan.Finding) { f.ID = "CVE-2026-2222" }), false},
