174			{"an absolute path that climbs out of the target", "/repo/../etc/passwd", target, true, "", reasonFileOutsideTarget},
175			{"the container mount that climbs out", "/scan/../etc/passwd", target, true, "", reasonFileOutsideTarget},
176			{"no file", "", target, true, "", reasonNoFile},
177			{"an image target has no file on disk", "k/x.yaml", "app:1.0", false, "", reasonFileNotOnDisk},
178			{"an image target, whatever the file", "/etc/passwd", "app:1.0", false, "", reasonFileNotOnDisk},
179		}
180		for _, tc := range tests {
181			t.Run(tc.name, func(t *testing.T) {
182				got, a := findingFilePath(scan.Finding{File: tc.file}, tc.target, tc.onDisk)
183				if a.Reason != tc.wantReason {
184					t.Errorf("reason = %q, want %q", a.Reason, tc.wantReason)
185				}
186				if a.Enabled() != (tc.wantReason == "") {
187					t.Errorf("Enabled() = %v for reason %q", a.Enabled(), a.Reason)
188				}
189				if got != tc.want {
190					t.Errorf("path = %q, want %q", got, tc.want)
191				}
192			})
193		}
194	}
