196	// findingFilePath answers for the header every frame and for the key: it never
197	// touches the disk. A file that does not exist is the viewer's to report (Rule
198	// 130, "Not knowing is not knowing it is a no"), so a path under a target that
199	// does not exist is still enabled.
200	func TestFindingFilePathDoesNotTouchTheDisk(t *testing.T) {
201		_, a := findingFilePath(scan.Finding{File: "no/such/file.yaml"}, "/definitely/not/a/directory", true)
202		if !a.Enabled() {
203			t.Errorf("a file that may not exist is refused (%q): the viewer says so, not the header", a.Reason)
204		}
205	
206		entries, err := os.ReadDir(".")
207		if err != nil {
208			t.Fatal(err)
209		}
210		fset := token.NewFileSet()
211		found := false
212		for _, entry := range entries {
213			name := entry.Name()
214			if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
215				continue
216			}
217			file, err := parser.ParseFile(fset, name, nil, 0)
218			if err != nil {
219				t.Fatal(err)
220			}
221			for _, decl := range file.Decls {
222				fn, ok := decl.(*ast.FuncDecl)
223				if !ok || fn.Name.Name != "findingFilePath" || fn.Body == nil {
224					continue
225				}
226				found = true
227				ast.Inspect(fn.Body, func(n ast.Node) bool {
228					sel, ok := n.(*ast.SelectorExpr)
229					if !ok {
230						return true
231					}
232					if id, ok := sel.X.(*ast.Ident); ok && (id.Name == "os" || id.Name == "ioutil" || id.Name == "fs") {
233						t.Errorf("findingFilePath calls %s.%s: it must do no I/O", id.Name, sel.Sel.Name)
234					}
235					return true
236				})
237			}
238		}
239		if !found {
240			t.Error("findingFilePath is not declared in a non-test file")
241		}
242	}
