244	// ── sameFinding (AC3) ────────────────────────────────────────────────────────
245	
246	func TestSameFinding(t *testing.T) {
247		base := ksv0001("Container 'web' of Deployment 'app' should set allowPrivilegeEscalation")
248		cve := cveWith("gomod", "go get golang.org/x/net@v0.7.0")
249		with := func(f scan.Finding, edit func(*scan.Finding)) scan.Finding { edit(&f); return f }
250	
251		tests := []struct {
252			name string
253			a, b scan.Finding
254			want bool
255		}{
256			{"the same finding", base, base, true},
257			{"the same finding on another line, as the fix moves it", base, with(base, func(f *scan.Finding) { f.Line += 1 }), true},
258			{"a new description is the same finding", base, with(base, func(f *scan.Finding) { f.Description = "Reworded" }), true},
259			{"another message", base, with(base, func(f *scan.Finding) { f.Message = "Container 'sidecar' of Deployment 'app'" }), false},
260			{"another title", base, with(base, func(f *scan.Finding) { f.Title = "Another title" }), false},
261			{"another file", base, with(base, func(f *scan.Finding) { f.File = "other.yaml" }), false},
262			{"another rule", base, with(base, func(f *scan.Finding) { f.ID = "KSV-0012" }), false},
263			{"another source", base, with(base, func(f *scan.Finding) { f.Source = scan.SourceKubeconform }), false},
264			{"a rule written with its AVD id is the same rule", with(base, func(f *scan.Finding) { f.ID = "DS002" }),
265				with(base, func(f *scan.Finding) { f.ID = "AVD-DS-0002" }), true},
266			{"the same CVE", cve, cve, true},
267			{"another version of the package", cve, with(cve, func(f *scan.Finding) { f.Version = "0.2.0" }), false},
268			{"another package", cve, with(cve, func(f *scan.Finding) { f.PkgName = "golang.org/x/text" }), false},
269			{"another CVE", cve, with(cve, func(f *scan.Finding) { f.ID = "CVE-2026-2222" }), false},
270		}
271		for _, tc := range tests {
272			t.Run(tc.name, func(t *testing.T) {
273				if got := sameFinding(tc.a, tc.b); got != tc.want {
274					t.Errorf("sameFinding = %v, want %v", got, tc.want)
275				}
276				if got := sameFinding(tc.b, tc.a); got != tc.want {
277					t.Errorf("sameFinding is not symmetric: reversed = %v, want %v", got, tc.want)
278				}
279			})
280		}
281	}
