444	// ── The Fix block (DEVDESK-751, AC1, AC2) ────────────────────────────────────
445	
446	// blockLabels are the labels of the Fix block and of the sections after it, in
447	// the order the detail shows them.
448	var blockLabels = []string{"Fix:", "Where:", "Do:", "Run:", "Effect:", "Warning:", "Why:", "Output:", "Refs:"}
449	
450	// labelAt is the index of the first line that starts with label, or -1.
451	func labelAt(lines []string, label string) int {
452		for i, line := range lines {
453			if strings.HasPrefix(strings.TrimSpace(line), label) {
454				return i
455			}
456		}
457		return -1
458	}
459	
460	func startsBlockLabel(line string) bool {
461		trimmed := strings.TrimSpace(line)
462		for _, label := range blockLabels {
463			if strings.HasPrefix(trimmed, label) {
464				return true
465			}
466		}
467		return false
468	}
469	
470	// labelledLines is the line that starts with label and the ones that continue it,
471	// up to the next label or the next blank line.
472	func labelledLines(lines []string, label string) []string {
473		at := labelAt(lines, label)
474		if at < 0 {
475			return nil
476		}
477		out := []string{lines[at]}
478		for _, next := range lines[at+1:] {
479			if strings.TrimSpace(next) == "" || startsBlockLabel(next) {
480				break
481			}
482			out = append(out, next)
483		}
484		return out
485	}
486	
487	// squash joins words with single spaces, so a text compares equal however it
488	// was wrapped.
489	func squash(text string) string { return strings.Join(strings.Fields(text), " ") }
490	
491	// labelledText is the wrapped text of one labelled line, squashed.
492	func labelledText(lines []string, label string) string {
493		return squash(strings.Join(labelledLines(lines, label), " "))
494	}
495	
496	func leadingSpaces(line string) int { return len(line) - len(strings.TrimLeft(line, " ")) }
497	
498	// columnWidth is the text width at a terminal width: one column, never wider
499	// than maxColumnWidth.
500	func columnWidth(width int) int { return min(width-4, 110) }
